WITH lines AS (SELECT id, log_ts, latency_ms, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, v), with_windows AS (SELECT latency_ms, k, v, CUME_DIST() OVER (PARTITION BY k ORDER BY latency_ms NULLS FIRST) AS latency_ms_cume_dist FROM lines), metrics AS (SELECT latency_ms, k, latency_ms_cume_dist, PERCENT_RANK() OVER w_hist AS latency_ms_cume_dist_percent_rank, DENSE_RANK() OVER (PARTITION BY k ORDER BY latency_ms_cume_dist DESC NULLS FIRST) AS latency_ms_cume_dist_dense_rank FROM with_windows WINDOW w_hist AS (PARTITION BY k ORDER BY latency_ms_cume_dist)), valid AS (SELECT k, latency_ms_cume_dist, latency_ms_cume_dist_percent_rank, latency_ms_cume_dist_dense_rank, CAST(latency_ms_cume_dist_dense_rank AS DOUBLE) AS latency_ms_cume_dist_dense_rank_num, COALESCE(k, 'UNKNOWN') AS k_filled FROM metrics WHERE k IS NOT NULL AND latency_ms_cume_dist_dense_rank > 7), filtered AS (SELECT *, COALESCE(latency_ms_cume_dist_dense_rank, 0) AS latency_ms_cume_dist_dense_rank_filled, COALESCE(k, 'UNKNOWN') AS k_filled_2 FROM valid WHERE k IS DISTINCT FROM 'version'), stats AS (SELECT CASE WHEN latency_ms_cume_dist >= 0.73 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_cume_dist_tier, SUM(CASE WHEN k = 'trace' THEN latency_ms_cume_dist_dense_rank_filled ELSE 0 END) AS trace_latency_ms_cume_dist_dense_rank_filled, APPROX_PERCENTILE(latency_ms_cume_dist_dense_rank_num, 0.5) AS latency_ms_cume_dist_dense_rank_num_p50, APPROX_PERCENTILE(latency_ms_cume_dist_percent_rank, 0.9) AS latency_ms_cume_dist_percent_rank_p90 FROM filtered GROUP BY latency_ms_cume_dist_tier) SELECT latency_ms_cume_dist_tier, latency_ms_cume_dist_dense_rank_num_p50 FROM stats ORDER BY latency_ms_cume_dist_tier DESC NULLS LAST LIMIT 20;
